const item = $input.first();
const base64Data = item.json.data.base64;
if (!base64Data) {
  throw new Error('No se encontró base64 en data.base64');
}
const mimeType = item.json.data.mimetype || 'audio/ogg; codecs=opus';
const fileName = item.json.data.fileName || 'audio.oga';
const ext = fileName.split('.').pop() || 'oga';
return [{
  json: { ...item.json },
  binary: {
    data: {
      data: base64Data,
      mimeType: mimeType,
      fileName: fileName,
      fileExtension: ext
    }
  }
}];

const webhookData = $('Webhook Evolution API').first().json;
const messageType = webhookData.body.data.messageType;

let userMessage = '';
let rawPhone = webhookData.body.data.key.remoteJid.replace('@s.whatsapp.net', '');
let phoneNumber = rawPhone.startsWith('598') ? rawPhone : '598' + rawPhone;
let pushName = webhookData.body.data.pushName || 'Usuario';

if (messageType === 'conversation') {
  userMessage = webhookData.body.data.message.conversation;
} else if (messageType === 'extendedTextMessage') {
  userMessage = webhookData.body.data.message.extendedTextMessage.text;
} else if (messageType === 'audioMessage') {
  try {
    const transcription = $('Transcribir con Whisper').first();
    userMessage = transcription.json.text || '[Audio no transcrito]';
  } catch (e) {
    userMessage = '[Error al transcribir audio]';
  }
}

if (!userMessage || userMessage.trim() === '') {
  userMessage = '[Mensaje vacío]';
}

return [{
  json: {
    chatInput: userMessage,
    sessionId: phoneNumber,
    phoneNumber: phoneNumber,
    // CORR v2: remoteJid completo para uso directo en nodos Evolution API
    remoteJid: phoneNumber + '@s.whatsapp.net',
    pushName: pushName,
    instanceName: webhookData.body.instance,
    messageType: messageType,
    canal: 'whatsapp',
    timestamp: new Date().toISOString()
  }
}];

