// ─── LIMPIAR OUTPUT NORMAL ─────────────────────────────────────────────
// FIX v2: fallback explícito si el agente no produce output (ej: fallo de tool)
const rawOutput = $input.first().json.output;

// Si el agente falló silenciosamente, output puede ser undefined/null/vacío
const output = (rawOutput && rawOutput.trim().length > 0)
  ? rawOutput
  : 'Disculpá, tuve un problema técnico justo ahora. ¿Podés repetir tu mensaje?';

const limpio = output
  .replace(/CITA_CONFIRMADA/g, '')
  .replace(/CITA_CANCELADA/g, '')
  .replace(/CITA_MODIFICADA/g, '')
  .replace(/ESCALAR_HUMANO/g, '')
  .trim();

const preparar = $('Preparar Datos').first().json;

return [{
  json: {
    ...($input.first().json),
    outputLimpio: limpio.length > 0 ? limpio : 'Disculpá, tuve un problema técnico. ¿Podés repetir tu mensaje?',
    instanceName: preparar.instanceName,
    remoteJid: preparar.remoteJid,
    pushName: preparar.pushName,
    phoneNumber: preparar.phoneNumber,
    outputOriginal: rawOutput || ''
  }
}];

